function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
function safeText(value){return String(value||'Request failed').split(/\r?\n/,1)[0].replace(/[A-Za-z]:\\[^\s\"']+/g,'<internal-path>').replace(/(^|\s)\/(?:[^\/\s]+\/)+[^\s\"']+/g,'$1<internal-path>').replace(/\b[a-fA-F0-9]{40,64}\b/g,'<internal-id>').slice(0,500)}
async function fetchJson(path,options={}){const response=await fetch(origin()+path,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});let payload=null;try{payload=await response.json()}catch{}if(!response.ok){const detail=payload&&payload.detail!==undefined?payload.detail:payload||{};const error=detail&&typeof detail==='object'?detail:{};throw new Error(JSON.stringify({status:'failed',error_code:String(error.code||'DATA_QUERY_FAILED'),error_summary:safeText(error.message||detail),http_status:response.status}))}return payload}
async function invoke(name,input){const payload=await fetchJson('/api/agent/data-tools/'+name+'/invoke',{method:'POST',body:JSON.stringify({input})});return payload.result}
function clean(value,depth=0){if(depth>5)return'[depth limited]';if(Array.isArray(value)){if(value.length<=10)return value.map(item=>clean(item,depth+1));return{count:value.length,head:value.slice(0,3).map(item=>clean(item,depth+1)),tail:value.slice(-3).map(item=>clean(item,depth+1)),truncated:true}}if(value&&typeof value==='object'){const out={};for(const [key,item] of Object.entries(value)){if(['path','root','sha256','source_sha256','traceback','stdout','stderr','error'].includes(key))continue;out[key]=clean(item,depth+1)}return out}return value}
function boundedRows(rows,limit){const count=rows.length;if(count<=limit)return{rows:clean(rows),row_count:count,rows_truncated:false};const head=Math.ceil(limit/2),tail=Math.floor(limit/2);return{rows:clean([...rows.slice(0,head),...rows.slice(count-tail)]),row_count:count,rows_truncated:true}}
function compact(payload,limit){if(Array.isArray(payload))return boundedRows(payload,limit);if(!payload||typeof payload!=='object')return{value:payload};const out=clean(payload);for(const key of ['rows','items','values','series'])if(Array.isArray(payload[key])){const sampled=boundedRows(payload[key],limit);out[key]=sampled.rows;out[key+'_count']=sampled.row_count;out[key+'_truncated']=sampled.rows_truncated}if('status'in out){out.data_status=out.status;delete out.status}return out}
function catalog(payload){const values=Array.isArray(payload)?payload:Array.isArray(payload?.datasets)?payload.datasets:[];return{status:'succeeded',data_status:Array.isArray(payload)?null:payload?.status||null,ready:Array.isArray(payload)?undefined:payload?.ready,total:values.length,datasets:values.map(item=>({id:item.id,label:item.label,status:item.status,configured:item.configured,rows:item.rows,date_start:item.date_start,date_end:item.date_end,symbol_count:item.symbol_count}))}}
async function run(input){const action=String(input.action||''),limit=Math.max(1,Math.min(50,Number(input.limit||10)));let payload;if(action==='catalog')return catalog(await invoke('data.catalog',{}));if(action==='status')return catalog(await invoke('data.status',{}));if(action==='query'){if(!input.dataset)throw new Error('dataset is required for query');const body={dataset:input.dataset,limit};for(const key of ['symbols','start','end','columns'])if(input[key]!==undefined)body[key]=input[key];payload=await invoke('data.query',body)}else if(action==='validate'){if(!input.dataset)throw new Error('dataset is required for validate');payload=await invoke('data.validate',{dataset:input.dataset})}else if(action==='market_bars'){const symbol=String(input.symbol||'').trim();if(!symbol)throw new Error('symbol is required for market_bars');const params=new URLSearchParams({symbol,profile:'runtime'});if(input.start)params.set('start',String(input.start));if(input.end)params.set('end',String(input.end));payload=await fetchJson('/api/data/market/bars?'+params)}else if(action==='fundamentals'){if(!Array.isArray(input.symbols)||!input.symbols.length)throw new Error('symbols are required for fundamentals');const params=new URLSearchParams({profile:'runtime',limit:String(limit)});for(const symbol of input.symbols)params.append('symbols',String(symbol));for(const field of input.fields||[])params.append('fields',String(field));if(input.start_quarter)params.set('start_quarter',String(input.start_quarter));if(input.end_quarter)params.set('end_quarter',String(input.end_quarter));if(input.asof_date)params.set('asof_date',String(input.asof_date));payload=await fetchJson('/api/data/fundamentals?'+params)}else if(action==='factor_returns'){const params=new URLSearchParams({profile:'runtime'});for(const name of input.names||[])params.append('names',String(name));if(input.start)params.set('start',String(input.start));if(input.end)params.set('end',String(input.end));payload=await fetchJson('/api/data/factors/returns?'+params)}else throw new Error('unsupported data query action');return{status:'succeeded',action,...compact(payload,limit)}}
